def _error_code(body: bytes) -> str:
    try:
        err = json.loads(body)["error"]
        if isinstance(err, dict):
            err = err["code"]
        return str(err)
    except (ValueError, KeyError, TypeError):
        return ""


def _call(transport: Transport, method: str, path: str, params: dict[str, str] | None = None, body: dict[str, Any] | None = None, ok: int = 200) -> Any:
    r = transport(method, path, dict(params or {}), body)
    if r.status != ok:
        raise ApiError(r.status, _error_code(r.body))
    return json.loads(r.body)


_TS = re.compile(r"(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d):(\d\d)(?:\.\d+)?Z")


def _parse_ts(s: str) -> datetime:
    m = _TS.fullmatch(s)
    if m is None:
        raise ValueError(f"bad timestamp {s!r}")
    return datetime(*(int(g) for g in m.groups()), tzinfo=timezone.utc)


def _fmt_ts(t: datetime) -> str:
    return t.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# v4 status -> the v3 status our code knows.
_STATUS = {
    "held": Status.PENDING,
    "booked": Status.CONFIRMED,
    "rescheduled": Status.CONFIRMED,
    "arrived": Status.CHECKED_IN,
    "departed": Status.COMPLETED,
    "canceled": Status.CANCELLED,
    "expired": Status.CANCELLED,
    "missed": Status.NO_SHOW,
}


def _v4_statuses(status: Status) -> list[str]:
    return [v for v, s in _STATUS.items() if s == status]


def _booking(b: dict[str, Any]) -> Booking:
    start = _parse_ts(b["starts_at"])
    end = _parse_ts(b["ends_at"])
    status = _STATUS[b["status"]]
    cancel_reason = None
    if b["status"] == "expired":
        cancel_reason = "hold_expired"
    elif b.get("cancellation"):
        cancel_reason = b["cancellation"].get("reason")
    return Booking(
        id=b["id"],
        dock=b["dock_id"],
        start=start,
        duration_min=int((end - start).total_seconds() // 60),
        carrier=b["carrier"]["name"],
        carrier_scac=b["carrier"]["scac"],
        trailer=b.get("trailer_number"),
        status=status,
        cancel_reason=cancel_reason,
    )

